import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"换模型时改什么","description":"换代后只改主动程度、啰嗦程度和停止条件。型号以官方 latest 页为准，本页不维护对照长文。","frontmatter":{"title":"换模型时改什么","description":"换代后只改主动程度、啰嗦程度和停止条件。型号以官方 latest 页为准，本页不维护对照长文。","domain":"tech","tags":["prompt"],"navOrder":40,"llm":[15],"prev":{"text":"写给仓库 · AGENTS.md","link":"/zh/tech/prompt/agents-doc"},"next":{"text":"附录 · System Prompts","link":"/zh/tech/prompt/system-prompts-collection"}},"headers":[],"relativePath":"zh/products/prompt/official-guide-2026.md","filePath":"zh/products/prompt/official-guide-2026.md","lastUpdated":1791173509000}'),o={name:"zh/products/prompt/official-guide-2026.md"};function n(p,t,l,i,d,c){return r(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="换模型时改什么" tabindex="-1">换模型时改什么 <a class="header-anchor" href="#换模型时改什么" aria-label="Permalink to &quot;换模型时改什么&quot;">​</a></h1><p><strong>结论</strong>：四块骨架不用推倒。换代后只调三件事——<strong>有多主动、有多啰嗦、何时停手</strong>。</p><blockquote><p><strong>路径位置</strong>：主路径第 4 步。还不会写任务 / 约束 / 输出，先回 <a href="/zh/tech/prompt/">怎么写 Prompt</a>。</p><p>「为什么新模型更字面、MUST 会过触发」的机制，应在 Learn LLM 第 15 章补齐（见 <a href="https://github.com/zenHeart/learn-llm/issues/2" target="_blank" rel="noreferrer">learn-llm#2</a>）。本页只给工程师检查清单。型号名以官方当天页面为准，不在本站维护。</p></blockquote><h2 id="先打开官方活页" tabindex="-1">先打开官方活页 <a class="header-anchor" href="#先打开官方活页" aria-label="Permalink to &quot;先打开官方活页&quot;">​</a></h2><table tabindex="0"><thead><tr><th>厂商</th><th>打开哪一页</th><th>你要找的句子</th></tr></thead><tbody><tr><td>OpenAI</td><td><a href="https://developers.openai.com/api/docs/guides/prompt-engineering" target="_blank" rel="noreferrer">Prompt engineering</a> · <a href="https://developers.openai.com/api/docs/guides/latest-model" target="_blank" rel="noreferrer">latest-model</a></td><td>要不要更瘦的 prompt、agent 何时停</td></tr><tr><td>Anthropic</td><td><a href="https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices" target="_blank" rel="noreferrer">Prompting best practices</a></td><td>字面遵循、verbosity、tool 过触发</td></tr><tr><td>Gemini</td><td><a href="https://ai.google.dev/gemini-api/docs/prompting-strategies" target="_blank" rel="noreferrer">Prompt design strategies</a></td><td>few-shot、Structured Output、agentic 收尾</td></tr></tbody></table><p>不要从本站或某篇 2026.05 摘要抄型号行为。摘要会过期。</p><h2 id="检查清单" tabindex="-1">检查清单 <a class="header-anchor" href="#检查清单" aria-label="Permalink to &quot;检查清单&quot;">​</a></h2><p>换快照或换厂商后，用同一条真实任务跑一遍：</p><ol><li><strong>主动程度</strong>。你说「可以改一下吗」，它是直接改文件，还是只给建议？不够主动就写「默认落地修改」；太主动就写「先列计划，等我说再改」。</li><li><strong>啰嗦程度</strong>。工具调用后它是跳下一项，还是写一段自我表扬？要可见进度就明确「每次工具后用两句话汇报」；要短就写「不要总结过程」。</li><li><strong>停止条件</strong>。它是否为了「更全面」再搜三轮？写清：核心问题已有证据就停；不要为了措辞再检索。</li><li><strong>禁止项语气</strong>。旧提示里的 <code>CRITICAL</code> / <code>ALWAYS</code> / <code>MUST use this tool</code> 在新模型上容易过触发。改成决策规则：「只有用户点名某工具，或缺少该工具拿不到的 ID 时才调用」。</li><li><strong>示例是否过期</strong>。指令改了三轮，few-shot 还是旧字段 → 模型跟示例。删掉或改到与当前 schema 一致。</li><li><strong>pin 快照</strong>。生产不要追 <code>latest</code>。换代是一次发版，带着 eval / fixture。</li></ol><h2 id="工程上怎么改提示" tabindex="-1">工程上怎么改提示 <a class="header-anchor" href="#工程上怎么改提示" aria-label="Permalink to &quot;工程上怎么改提示&quot;">​</a></h2><p><strong>过指定（旧习惯，新模型容易又慢又爱调工具）：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先读 A，再读 B，再逐字段对比，再想所有例外，</span></span>
<span class="line"><span>再决定调哪个工具，再调用，再解释全过程。</span></span>
<span class="line"><span>ALWAYS 使用 web_search。CRITICAL: 必须再检查一遍。</span></span></code></pre></div><p><strong>结果 + 停止条件（换代后优先）：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这个问题从头到尾做完。</span></span>
<span class="line"><span>成功标准：</span></span>
<span class="line"><span>- 结论来自仓库里已有的政策或代码，而不是猜测</span></span>
<span class="line"><span>- 允许的动作在回复前做完</span></span>
<span class="line"><span>- 回复只含 completed_actions、customer_message、blockers</span></span>
<span class="line"><span>停手：每次工具结果后问「现在能回答核心问题了吗？」能就停。</span></span>
<span class="line"><span>不要为了润色再搜索。</span></span></code></pre></div><p>把这段放进代码里的 <code>buildPrompt()</code>，不要只活在聊天记录里。</p><h2 id="实战信号" tabindex="-1">实战信号 <a class="header-anchor" href="#实战信号" aria-label="Permalink to &quot;实战信号&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>先改哪</th></tr></thead><tbody><tr><td>新模型不改文件，只给 diff 建议</td><td>主动程度：写「直接改，不要只建议」</td></tr><tr><td>新模型改了一堆没要的文件</td><td>范围：点名路径 + 「不要动其他目录」</td></tr><tr><td>又搜又读，迟迟不答</td><td>停止条件 + 检索预算</td></tr><tr><td>工具乱触发</td><td>删 MUST，改成「何时用 / 何时不用」</td></tr><tr><td>输出突然变成长篇散文</td><td>显式要长度和格式；Claude 近期型号对 verbosity 要单独写</td></tr><tr><td>旧 JSON 头 prefill 报 400</td><td>不要再 prefill；走 <a href="/zh/tech/prompt/json-prompt-best-practices.html">Schema</a></td></tr></tbody></table><h2 id="不是本页" tabindex="-1">不是本页 <a class="header-anchor" href="#不是本页" aria-label="Permalink to &quot;不是本页&quot;">​</a></h2><ul><li>某个型号的完整性格评测</li><li>记忆、截断、prompt caching 的原理 → <a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">第 15 章</a></li><li>某个 IDE 的点击路径 → <a href="/zh/products/">产品</a></li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>附录才是查阅别人怎么写系统提示：<a href="/zh/tech/prompt/system-prompts-collection.html">System Prompts</a>。日常任务仍回 <a href="/zh/tech/prompt/">怎么写</a>。</p>`,21)])])}const f=e(o,[["render",n]]);export{b as __pageData,f as default};
